+import { useState } from 'react';
+import copy from '../copy/en.json';
+import { RoundButton } from '../components/RoundButton';
+import { ParentGate } from '../components/ParentGate';
+import { loadProgress, saveProgress } from '../data/progress';
+
+const NAME_MAX = 20;
+const text = copy.grownUps.settings;
+
+// Grown-up screen: always opened through the parental gate (PARENTS.md).
+export function SettingsScreen({ onDone }) {
+  return (
+    <ParentGate onCancel={onDone}>
+      <SettingsForm onDone={onDone} />
+    </ParentGate>
+  );
+}
+
+function SettingsForm({ onDone }) {
+  const [saved, setSaved] = useState(loadProgress);
+  const [name, setName] = useState(saved.name);
+  const [reminders, setReminders] = useState(saved.reminders);
+  const [error, setError] = useState('');
+  const [status, setStatus] = useState('');
+
+  const dirty = name !== saved.name || reminders !== saved.reminders;
+
+  function handleSubmit(e) {
+    e.preventDefault();
+    const trimmed = name.trim();
+    if (!trimmed) {
+      setError(text.nameEmpty);
+      return;
+    }
+    if (trimmed.length > NAME_MAX) {
+      setError(text.nameTooLong.replace('{n}', NAME_MAX));
+      return;
+    }
+    // Re-read so we never overwrite seeds or sprouts earned meanwhile.
+    const next = { ...loadProgress(), name: trimmed, reminders };
+    saveProgress(next);
+    setSaved(next);
+    setName(trimmed);
+    setError('');
+    setStatus(text.saved);
+  }
+
+  return (
+    <main
+      className="settings"
+      style={{
+        background: 'var(--sprout-cream)',
+        color: 'var(--sprout-ink)',
+        fontFamily: 'var(--sprout-font)',
+        fontSize: 'var(--sprout-text-body)',
+        lineHeight: 'var(--sprout-line)',
+        padding: 'var(--sprout-gap)',
+        maxWidth: '36em',
+        margin: '0 auto',
+        minHeight: '100dvh',
+      }}
+    >
+      <h1 style={{ fontSize: 'var(--sprout-text-title)' }}>{text.title}</h1>
+
+      <form onSubmit={handleSubmit} noValidate style={{ display: 'grid', gap: 'var(--sprout-gap)' }}>
+        <div style={{ display: 'grid', gap: 'calc(var(--sprout-gap) / 2)' }}>
+          <label htmlFor="settings-name" style={{ fontWeight: 700 }}>{text.nameLabel}</label>
+          <p id="settings-name-help" style={{ margin: 0 }}>{text.nameHelp}</p>
+          <input
+            id="settings-name"
+            type="text"
+            autoComplete="off"
+            value={name}
+            aria-describedby={error ? 'settings-name-help settings-name-error' : 'settings-name-help'}
+            aria-invalid={Boolean(error)}
+            onChange={(e) => { setName(e.target.value); setError(''); setStatus(''); }}
+            style={{
+              minHeight: 'var(--sprout-tap)',
+              borderRadius: 'var(--sprout-radius-pill)',
+              border: `3px solid ${error ? 'var(--sprout-alert)' : 'var(--sprout-leaf-deep)'}`,
+              padding: '0 var(--sprout-gap)',
+              fontSize: 'var(--sprout-text-body)',
+              fontFamily: 'inherit',
+              color: 'var(--sprout-ink)',
+              background: 'white',
+            }}
+          />
+          {error && (
+            <p id="settings-name-error" style={{ margin: 0, color: 'var(--sprout-alert)', fontWeight: 700 }}>
+              {error}
+            </p>
+          )}
+        </div>
+
+        <fieldset style={{ border: 0, padding: 0, margin: 0, display: 'grid', gap: 'calc(var(--sprout-gap) / 2)' }}>
+          <legend style={{ fontWeight: 700, padding: 0 }}>{text.remindersTitle}</legend>
+          <label
+            htmlFor="settings-reminders"
+            style={{
+              display: 'flex',
+              alignItems: 'center',
+              gap: 'var(--sprout-gap)',
+              minHeight: 'var(--sprout-tap)',
+              padding: '0 var(--sprout-gap)',
+              borderRadius: 'var(--sprout-radius-blob)',
+              background: 'white',
+              cursor: 'pointer',
+            }}
+          >
+            <input
+              id="settings-reminders"
+              type="checkbox"
+              role="switch"
+              checked={reminders}
+              aria-describedby="settings-reminders-help"
+              onChange={(e) => { setReminders(e.target.checked); setStatus(''); }}
+              style={{ width: '32px', height: '32px', accentColor: 'var(--sprout-leaf-deep)', flexShrink: 0 }}
+            />
+            <span>{text.remindersLabel}</span>
+          </label>
+          <p id="settings-reminders-help" style={{ margin: 0 }}>{text.remindersHelp}</p>
+        </fieldset>
+
+        <RoundButton type="submit" disabled={!dirty}>{text.save}</RoundButton>
+        <p role="status" style={{ margin: 0, minHeight: '1.5em' }}>{status}</p>
+      </form>
+
+      <RoundButton tone="sky" onClick={onDone}>{text.back}</RoundButton>
+    </main>
+  );
+}
