+++ b/src/pages/AccountSettings.tsx
@@ -0,0 +1,147 @@
+import { useState } from 'react';
+import { Field, Button } from '../ui';
+import { PERMISSIONS, requirePermission, type Permission } from '../auth/permissions';
+import { audit } from '../audit/log';
+
+export type NotificationTopic = {
+  id: string;
+  label: string;
+  hint?: string;
+  enabled: boolean;
+};
+
+export type AccountSettingsValues = {
+  displayName: string;
+  notifications: Record<string, boolean>;
+};
+
+type Props = {
+  staff: { id: string; permissions: Permission[] };
+  displayName: string;
+  notificationTopics: NotificationTopic[];
+  onSave: (values: AccountSettingsValues) => Promise<void>;
+};
+
+const DISPLAY_NAME_MAX = 64;
+
+function validateDisplayName(value: string): string | undefined {
+  const trimmed = value.trim();
+  if (trimmed.length === 0) return 'Enter a display name.';
+  if (trimmed.length > DISPLAY_NAME_MAX) return `Display name must be ${DISPLAY_NAME_MAX} characters or fewer.`;
+  return undefined;
+}
+
+export function AccountSettings({ staff, displayName, notificationTopics, onSave }: Props) {
+  requirePermission(staff, PERMISSIONS.PROFILE_EDIT_SELF);
+
+  const initialNotifications = Object.fromEntries(notificationTopics.map((t) => [t.id, t.enabled]));
+
+  const [name, setName] = useState(displayName);
+  const [notifications, setNotifications] = useState<Record<string, boolean>>(initialNotifications);
+  const [nameError, setNameError] = useState<string>();
+  const [saveError, setSaveError] = useState<string>();
+  const [savedAt, setSavedAt] = useState<string>();
+  const [saving, setSaving] = useState(false);
+  const [saved, setSaved] = useState({ displayName, notifications: initialNotifications });
+
+  const changedTopics = notificationTopics.filter((t) => notifications[t.id] !== saved.notifications[t.id]);
+  const nameChanged = name.trim() !== saved.displayName;
+  const hasChanges = nameChanged || changedTopics.length > 0;
+
+  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
+    event.preventDefault();
+    setSaveError(undefined);
+    setSavedAt(undefined);
+
+    const error = validateDisplayName(name);
+    setNameError(error);
+    if (error) return;
+    if (!hasChanges) return;
+
+    const values = { displayName: name.trim(), notifications };
+    const changed = [nameChanged && 'display name', changedTopics.length > 0 && 'notification preferences']
+      .filter(Boolean)
+      .join(' and ');
+
+    setSaving(true);
+    try {
+      requirePermission(staff, PERMISSIONS.PROFILE_EDIT_SELF);
+      await onSave(values);
+      await audit.record({
+        actor: staff.id,
+        action: 'profile.update.self',
+        target: staff.id,
+        reason: `Staff member changed own ${changed}.`,
+      });
+      setSaved(values);
+      setName(values.displayName);
+      setSavedAt(formatUtc(new Date()));
+    } catch {
+      setSaveError('Changes were not saved. Check your connection and select "Save changes" again.');
+    } finally {
+      setSaving(false);
+    }
+  }
+
+  return (
+    <main className="ld-page">
+      <h1>Account settings</h1>
+
+      <form onSubmit={handleSubmit} noValidate aria-busy={saving}>
+        <section aria-labelledby="settings-profile">
+          <h2 id="settings-profile">Profile</h2>
+          <Field
+            id="display-name"
+            label="Display name"
+            hint="Shown to other staff in case notes and the audit trail. Your staff ID does not change."
+            error={nameError}
+          >
+            <input
+              name="displayName"
+              value={name}
+              maxLength={DISPLAY_NAME_MAX}
+              autoComplete="name"
+              onChange={(e) => {
+                setName(e.target.value);
+                if (nameError) setNameError(validateDisplayName(e.target.value));
+              }}
+            />
+          </Field>
+        </section>
+
+        <section aria-labelledby="settings-notifications">
+          <h2 id="settings-notifications">Notifications</h2>
+          {notificationTopics.length === 0 ? (
+            <p>No notification topics are available for your role. Contact your team lead to request access.</p>
+          ) : (
+            <fieldset>
+              <legend>Notify me about</legend>
+              {notificationTopics.map((topic) => (
+                <Field key={topic.id} id={`notify-${topic.id}`} label={topic.label} hint={topic.hint}>
+                  <input
+                    type="checkbox"
+                    name={`notify-${topic.id}`}
+                    checked={notifications[topic.id] ?? false}
+                    onChange={(e) => setNotifications((prev) => ({ ...prev, [topic.id]: e.target.checked }))}
+                  />
+                </Field>
+              ))}
+            </fieldset>
+          )}
+        </section>
+
+        <div className="ld-toolbar">
+          <Button type="submit" variant="primary" disabled={saving || !hasChanges}>
+            {saving ? 'Saving changes' : 'Save changes'}
+          </Button>
+          <p role="status">{savedAt && !hasChanges ? `Changes saved ${savedAt}.` : ''}</p>
+          {saveError && <p role="alert" className="ld-field__error">{saveError}</p>}
+        </div>
+      </form>
+    </main>
+  );
+}
+
+function formatUtc(date: Date): string {
+  return `${date.toISOString().slice(0, 16).replace('T', ' ')} UTC`;
+}

