diff --git a/src/commands/config.js b/src/commands/config.js
new file mode 100644
index 0000000..7e1e55c
--- /dev/null
+++ b/src/commands/config.js
@@ -0,0 +1,54 @@
+import { KEYS, readConfig, readUserConfig, writeConfig } from '../config.js';
+import { fail } from '../output.js';
+
+const keyList = Object.keys(KEYS).join(', ');
+
+function checkKey(cmd, key) {
+  if (!key) fail(`config ${cmd}: missing <key>`, `usage: logq config ${cmd} <key>${cmd === 'set' ? ' <value>' : ''}`);
+  if (!KEYS[key]) fail(`config ${cmd}: unknown key: ${key}`, `keys: ${keyList}`);
+}
+
+function print(key, value, json) {
+  process.stdout.write(json ? `${JSON.stringify({ key, value })}\n` : `${key}=${value}\n`);
+}
+
+export async function config([sub, ...rest]) {
+  const json = rest.includes('--json');
+  const args = rest.filter((a) => a !== '--json');
+
+  if (sub === 'ls') {
+    for (const [key, value] of Object.entries(readConfig())) {
+      if (KEYS[key]) print(key, value, json);
+    }
+    return 0;
+  }
+
+  if (sub === 'get') {
+    const [key] = args;
+    checkKey('get', key);
+    const value = readConfig()[key];
+    if (json) print(key, value, true);
+    else process.stdout.write(`${value}\n`);
+    return 0;
+  }
+
+  if (sub === 'set') {
+    const [key, raw] = args;
+    checkKey('set', key);
+    if (raw === undefined) fail('config set: missing <value>', `usage: logq config set ${key} <${KEYS[key].hint}>`);
+    const value = KEYS[key].parse(raw);
+    if (value === undefined) fail(`config set: invalid value for ${key}: ${JSON.stringify(raw)}`, `expected: ${KEYS[key].hint}`);
+    writeConfig({ ...readUserConfig(), [key]: value });
+    return 0;
+  }
+
+  if (sub === 'unset') {
+    const [key] = args;
+    checkKey('unset', key);
+    const { [key]: _, ...kept } = readUserConfig();
+    writeConfig(kept);
+    return 0;
+  }
+
+  fail(`config: unknown subcommand: ${sub ?? '(none)'}`, 'try: logq config ls');
+}
