+++ b/test/config.test.js
@@ -0,0 +1,67 @@
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { spawnSync } from 'node:child_process';
+import fs from 'node:fs';
+import os from 'node:os';
+import path from 'node:path';
+
+const bin = new URL('../bin/logq.js', import.meta.url).pathname;
+
+function setup() {
+  const home = fs.mkdtempSync(path.join(os.tmpdir(), 'logq-'));
+  const env = { ...process.env, XDG_CONFIG_HOME: home, XDG_DATA_HOME: home };
+  const logq = (...args) => spawnSync(process.execPath, [bin, ...args], { env, encoding: 'utf8' });
+  const file = path.join(home, 'logq', 'config.json');
+  return { logq, file };
+}
+
+test('ls prints defaults when no config file exists', () => {
+  const { logq } = setup();
+  const r = logq('config', 'ls');
+  assert.equal(r.status, 0);
+  assert.match(r.stdout, /^notify=off$/m);
+  assert.match(r.stdout, /^name=$/m);
+});
+
+test('set name and notify, then get them back', () => {
+  const { logq, file } = setup();
+  assert.equal(logq('config', 'set', 'name', '  Ada Lovelace ').status, 0);
+  assert.equal(logq('config', 'set', 'notify', 'on').status, 0);
+  assert.equal(logq('config', 'get', 'name').stdout, 'Ada Lovelace\n');
+  assert.deepEqual(JSON.parse(logq('config', 'get', '--json', 'notify').stdout), { key: 'notify', value: 'on' });
+  assert.deepEqual(JSON.parse(fs.readFileSync(file, 'utf8')), { name: 'Ada Lovelace', notify: 'on' });
+});
+
+test('ls --json prints one object per line', () => {
+  const { logq } = setup();
+  const lines = logq('config', 'ls', '--json').stdout.trim().split('\n').map((l) => JSON.parse(l));
+  assert.deepEqual(lines.find((l) => l.key === 'limit'), { key: 'limit', value: 1000 });
+});
+
+test('unset restores the default', () => {
+  const { logq } = setup();
+  logq('config', 'set', 'notify', 'on');
+  assert.equal(logq('config', 'unset', 'notify').status, 0);
+  assert.equal(logq('config', 'get', 'notify').stdout, 'off\n');
+});
+
+test('invalid value exits 2 with the expected values on stderr', () => {
+  const { logq, file } = setup();
+  const r = logq('config', 'set', 'notify', 'yes');
+  assert.equal(r.status, 2);
+  assert.equal(r.stdout, '');
+  assert.equal(r.stderr, 'logq: config set: invalid value for notify: "yes"\nexpected: on|off\n');
+  assert.equal(fs.existsSync(file), false);
+});
+
+test('empty name is rejected', () => {
+  const { logq } = setup();
+  assert.equal(logq('config', 'set', 'name', '   ').status, 2);
+

