+import { useState } from 'react';
+import copy from '../copy/en.json';
+import { ParentGate } from '../components/ParentGate';
+import { RoundButton } from '../components/RoundButton';
+import { loadProgress, saveProgress } from '../data/progress';
+
+const NAME_MAX = 20;
+const t = copy.grownUps.settings;
+
+const fieldStyle = {
+  display: 'grid',
+  gap: 'calc(var(--sprout-gap) / 2)',
+  padding: 'var(--sprout-gap)',
+  border: '3px solid var(--sprout-sky)',
+  borderRadius: 'var(--sprout-radius-blob)',
+  background: 'var(--sprout-paper)',
+};
+
+function validateName(value) {
+  const name = value.trim();
+  if (!name) return t.nameErrorEmpty;
+  if (name.length > NAME_MAX) return t.nameErrorLong.replace('{n}', NAME_MAX);
+  if (name.includes('@')) return t.nameErrorEmail;
+  return '';
+}
+
+function SettingsForm({ onBack }) {
+  const [initial] = useState(loadProgress);
+  const [name, setName] = useState(initial.name);
+  const [reminders, setReminders] = useState(initial.reminders);
+  const [nameError, setNameError] = useState('');
+  const [saved, setSaved] = useState(false);
+
+  function handleSubmit(e) {
+    e.preventDefault();
+    const error = validateName(name);
+    setNameError(error);
+    if (error) {
+      setSaved(false);
+      return;
+    }
+    // Re-read so we never overwrite seeds or stories earned since this screen opened.
+    saveProgress({ ...loadProgress(), name: name.trim(), reminders });
+    setSaved(true);
+  }
+
+  return (
+    <main
+      style={{
+        minHeight: '100dvh',
+        boxSizing: 'border-box',
+        padding: 'var(--sprout-gap)',
+        paddingBottom: 'max(var(--sprout-gap), env(safe-area-inset-bottom))',
+        background: 'var(--sprout-cream)',
+        color: 'var(--sprout-ink)',
+        fontFamily: 'var(--sprout-font)',
+        fontSize: 'var(--sprout-text-body)',
+        lineHeight: 'var(--sprout-line)',
+      }}
+    >
+      <form
+        onSubmit={handleSubmit}
+        noValidate
+        style={{ display: 'grid', gap: 'var(--sprout-gap)', maxWidth: '36rem', margin: '0 auto' }}
+      >
+        <h1 style={{ fontSize: 'var(--sprout-text-title)', margin: 0 }}>{t.title}</h1>
+
+        <div style={fieldStyle}>
+          <label htmlFor="settings-name" style={{ fontWeight: 700 }}>{t.nameLabel}</label>
+          <p id="settings-name-help" style={{ margin: 0 }}>{t.nameHelp}</p>
+          <input
+            id="settings-name"
+            type="text"
+            autoComplete="off"
+            maxLength={NAME_MAX + 10}
+            value={name}
+            onChange={(e) => { setName(e.target.value); setSaved(false); }}
+            aria-invalid={nameError ? 'true' : undefined}
+            aria-describedby={nameError ? 'settings-name-help settings-name-error' : 'settings-name-help'}
+            style={{
+              minHeight: 'var(--sprout-tap)',
+              boxSizing: 'border-box',
+              padding: '0 var(--sprout-gap)',
+              border: `3px solid ${nameError ? 'var(--sprout-alert)' : 'var(--sprout-leaf-deep)'}`,
+              borderRadius: 'var(--sprout-radius-pill)',
+              font: 'inherit',
+              color: 'inherit',
+              background: 'var(--sprout-paper)',
+            }}
+          />
+          {nameError && (
+            <p id="settings-name-error" style={{ margin: 0, color: 'var(--sprout-alert)', fontWeight: 700 }}>
+              {nameError}
+            </p>
+          )}
+        </div>
+
+        <div style={fieldStyle}>
+          <label
+            htmlFor="settings-reminders"
+            style={{ display: 'flex', alignItems: 'center', gap: 'var(--sprout-gap)', minHeight: 'var(--sprout-tap)', fontWeight: 700, cursor: 'pointer' }}
+          >
+            <input
+              id="settings-reminders"
+              type="checkbox"
+              role="switch"
+              checked={reminders}
+              onChange={(e) => { setReminders(e.target.checked); setSaved(false); }}
+              aria-describedby="settings-reminders-help"
+              style={{ width: 32, height: 32, margin: 0, accentColor: 'var(--sprout-leaf-deep)', flex: 'none' }}
+            />
+            {t.remindersLabel}
+          </label>
+          <p id="settings-reminders-help" style={{ margin: 0 }}>{copy.grownUps.goalHelp}</p>
+        </div>
+
+        <RoundButton type="submit">{t.save}</RoundButton>
+        <p role="status" aria-live="polite" style={{ margin: 0, minHeight: '1.5em', color: 'var(--sprout-leaf-deep)', fontWeight: 700 }}>
+          {saved ? t.saved : ''}
+        </p>
+        <RoundButton tone="sky" onClick={onBack}>{t.back}</RoundButton>
+      </form>
+    </main>
+  );
+}
+
+// Grown-up area: always behind the parental gate (see PARENTS.md).
+export function SettingsScreen({ onBack }) {
+  return (
+    <ParentGate onCancel={onBack}>
+      <SettingsForm onBack={onBack} />
+    </ParentGate>
+  );
+}
