diff --git a/src/pages/AccountSettings.tsx b/src/pages/AccountSettings.tsx
new file mode 100644
index 0000000..4fae068
--- /dev/null
+++ b/src/pages/AccountSettings.tsx
@@ -0,0 +1,148 @@
+import { useState } from 'react';
+import { Field, Fieldset, Checkbox, Button } from '../ui';
+import { PERMISSIONS, requirePermission, type Permission } from '../auth/permissions';
+import { audit } from '../audit/log';
+
+export type NotificationPreferences = { email: boolean; types: Record<string, boolean> };
+
+type NotificationType = { key: string; label: string; hint?: string };
+
+// Placeholder list: replace with the notification types the backend actually sends.
+export const DEFAULT_NOTIFICATION_TYPES: NotificationType[] = [
+  { key: 'export.ready', label: 'Export ready for download', hint: 'Exports expire after 7 days.' },
+  { key: 'freeze.review', label: 'Account freeze awaiting my review' },
+  { key: 'permissions.changed', label: 'Changes to my permissions' },
+];
+
+const DISPLAY_NAME_MAX = 64;
+
+type Props = {
+  staff: { id: string; displayName: string; permissions: Permission[] };
+  preferences: NotificationPreferences;
+  notificationTypes?: NotificationType[];
+  onSave: (changes: { displayName: string; preferences: NotificationPreferences }) => Promise<void>;
+};
+
+function validateDisplayName(value: string): string | undefined {
+  const name = value.trim();
+  if (!name) return 'Enter a display name.';
+  if (name.length > DISPLAY_NAME_MAX) return `Display name must be ${DISPLAY_NAME_MAX} characters or fewer. It is ${name.length}.`;
+  return undefined;
+}
+
+function formatUtc(date: Date) {
+  return `${date.toISOString().slice(0, 16).replace('T', ' ')} UTC`;
+}
+
+export function AccountSettings({ staff, preferences, notificationTypes = DEFAULT_NOTIFICATION_TYPES, onSave }: Props) {
+  requirePermission(staff, PERMISSIONS.PROFILE_EDIT_SELF);
+
+  const [saved, setSaved] = useState({ displayName: staff.displayName, preferences });
+  const [displayName, setDisplayName] = useState(staff.displayName);
+  const [prefs, setPrefs] = useState(preferences);
+  const [nameError, setNameError] = useState<string>();
+  const [status, setStatus] = useState<{ kind: 'saved' | 'error'; message: string }>();
+  const [saving, setSaving] = useState(false);
+
+  const nameChanged = displayName.trim() !== saved.displayName;
+  const prefsChanged = JSON.stringify(prefs) !== JSON.stringify(saved.preferences);
+
+  function setType(key: string, enabled: boolean) {
+    setPrefs((p) => ({ ...p, types: { ...p.types, [key]: enabled } }));
+  }
+
+  function discard() {
+    setDisplayName(saved.displayName);
+    setPrefs(saved.preferences);
+    setNameError(undefined);
+    setStatus(undefined);
+  }
+
+  async function submit(event: React.FormEvent) {
+    event.preventDefault();
+    const error = validateDisplayName(displayName);
+    setNameError(error);
+    if (error) {
+      setStatus(undefined);
+      return;
+    }
+    if (!nameChanged && !prefsChanged) {
+      setStatus({ kind: 'saved', message: 'No changes to save.' });
+      return;
+    }
+
+    const next = { displayName: displayName.trim(), preferences: prefs };
+    setSaving(true);
+    setStatus(undefined);
+    try {
+      await onSave(next);
+      const target = `staff:${staff.id}`;
+      const reason = 'Self-service settings change';
+      if (nameChanged) await audit.record({ actor: staff.id, action: 'profile.display_name.update', target, reason });
+      if (prefsChanged) await audit.record({ actor: staff.id, action: 'profile.notifications.update', target, reason });
+      setSaved(next);
+      setDisplayName(next.displayName);
+      setStatus({ kind: 'saved', message: `Changes saved ${formatUtc(new Date())}.` });
+    } catch {
+      setStatus({ kind: 'error', message: 'Changes not saved. The settings service did not respond. Try again; if it fails again, contact the service desk.' });
+    } finally {
+      setSaving(false);
+    }
+  }
+
+  return (
+    <main className="ld-page">
+      <h1>Account settings</h1>
+      <form onSubmit={submit} noValidate>
+        <Fieldset id="profile" legend="Profile">
+          <Field
+            id="display-name"
+            label="Display name"
+            hint={`Shown to other staff in LedgerDesk. Your staff ID (${staff.id}) does not change. Maximum ${DISPLAY_NAME_MAX} characters.`}
+            error={nameError}
+          >
+            <input
+              name="displayName"
+              autoComplete="name"
+              value={displayName}
+              onChange={(e) => setDisplayName(e.target.value)}
+              onBlur={() => nameError && setNameError(validateDisplayName(displayName))}
+            />
+          </Field>
+        </Fieldset>
+
+        <Fieldset id="notify-types" legend="Notifications" hint="Choose which events notify you in LedgerDesk.">
+          {notificationTypes.map((t) => (
+            <Checkbox
+              key={t.key}
+              id={`notify-${t.key}`}
+              label={t.label}
+              hint={t.hint}
+              checked={Boolean(prefs.types[t.key])}
+              onChange={(e) => setType(t.key, e.target.checked)}
+            />
+          ))}
+        </Fieldset>
+
+        <Fieldset id="notify-delivery" legend="Delivery">
+          <Checkbox
+            id="notify-email"
+            label="Also send selected notifications by email"
+            hint="Sent to your work email address."
+            checked={prefs.email}
+            onChange={(e) => setPrefs((p) => ({ ...p, email: e.target.checked }))}
+          />
+        </Fieldset>
+
+        <div className="ld-toolbar">
+          <Button type="submit" variant="primary" disabled={saving} aria-busy={saving}>
+            {saving ? 'Saving changes' : 'Save changes'}
+          </Button>
+          <Button onClick={discard} disabled={saving || (!nameChanged && !prefsChanged)}>Discard changes</Button>
+          <p role="status" className="ld-field__hint">{status?.kind === 'saved' && status.message}</p>
+          <p role="alert" className="ld-field__error">{status?.kind === 'error' && status.message}</p>
+        </div>
+      </form>
+    </main>
+  );
+}
