@@ -0,0 +1,108 @@
+import { useState } from 'react';
+import copy from '../copy/en.json';
+import { ParentGate } from '../components/ParentGate';
+import { RoundButton } from '../components/RoundButton';
+import { loadProgress, saveProgress } from '../data/progress';
+
+const t = copy.grownUps.settings;
+const NAME_MAX = 20;
+// First name or nickname only (PARENTS.md): letters, spaces, hyphens, apostrophes.
+const NAME_PATTERN = /^[\p{L}][\p{L} '’-]*$/u;
+
+export function validateName(raw) {
+  const name = raw.trim().replace(/\s+/g, ' ');
+  if (!name) return { error: t.nameEmpty };
+  if (name.length > NAME_MAX) return { error: t.nameTooLong.replace('{n}', NAME_MAX) };
+  if (!NAME_PATTERN.test(name)) return { error: t.nameInvalid };
+  return { name };
+}
+
+const textStyle = { fontSize: 'var(--sprout-text-body)', lineHeight: 'var(--sprout-line)' };
+
+function SettingsForm({ onDone }) {
+  const [saved] = useState(loadProgress);
+  const [name, setName] = useState(saved.name);
+  const [reminders, setReminders] = useState(saved.reminders);
+  const [error, setError] = useState('');
+  const [status, setStatus] = useState('');
+
+  function handleSave(e) {
+    e.preventDefault();
+    const result = validateName(name);
+    if (result.error) {
+      setError(result.error);
+      setStatus('');
+      return;
+    }
+    // Re-read so we never overwrite seeds or stories earned since this screen opened.
+    saveProgress({ ...loadProgress(), name: result.name, reminders });
+    setName(result.name);
+    setError('');
+    setStatus(t.saved);
+  }
+
+  return (
+    <main
+      className="settings"
+      style={{ background: 'var(--sprout-cream)', color: 'var(--sprout-ink)', fontFamily: 'var(--sprout-font)', padding: 'var(--sprout-gap)', ...textStyle }}
+    >
+      <h1 style={{ fontSize: 'var(--sprout-text-title)' }}>{t.title}</h1>
+
+      <form onSubmit={handleSave} noValidate style={{ display: 'grid', gap: 'var(--sprout-gap)' }}>
+        <div style={{ display: 'grid', gap: 8 }}>
+          <label htmlFor="settings-name">{t.nameLabel}</label>
+          <input
+            id="settings-name"
+            value={name}
+            maxLength={NAME_MAX + 10}
+            autoComplete="off"
+            aria-describedby="settings-name-help settings-name-error"
+            aria-invalid={Boolean(error)}
+            onChange={(e) => { setName(e.target.value); setStatus(''); }}
+            style={{ ...textStyle, minHeight: 'var(--sprout-tap)', borderRadius: 'var(--sprout-radius-pill)', padding: '0 24px', border: '2px solid var(--sprout-leaf-deep)' }}
+          />
+          <p id="settings-name-help" style={{ margin: 0 }}>{t.nameHelp}</p>
+          <p id="settings-name-error" role="alert" style={{ margin: 0, color: 'var(--sprout-soil)', fontWeight: 700 }}>{error}</p>
+        </div>
+
+        <fieldset style={{ border: 0, padding: 0, margin: 0, display: 'grid', gap: 8 }}>
+          <legend style={{ fontWeight: 700, marginBottom: 8 }}>{t.notificationsTitle}</legend>
+          <button
+            type="button"
+            role="switch"
+            aria-checked={reminders}
+            aria-describedby="settings-reminders-help"
+            onClick={() => { setReminders((on) => !on); setStatus(''); }}
+            style={{
+              ...textStyle,
+              minHeight: 'var(--sprout-tap)',
+              borderRadius: 'var(--sprout-radius-pill)',
+              border: '2px solid var(--sprout-leaf-deep)',
+              background: reminders ? 'var(--sprout-leaf)' : 'var(--sprout-cream)',
+              color: reminders ? '#fff' : 'var(--sprout-ink)',
+              padding: '0 24px',
+              textAlign: 'left',
+              transition: 'background 200ms var(--sprout-bounce)',
+            }}
+          >
+            {t.remindersLabel}: {reminders ? t.on : t.off}
+          </button>
+          <p id="settings-reminders-help" style={{ margin: 0 }}>{t.remindersHelp}</p>
+        </fieldset>
+
+        <RoundButton type="submit">{t.save}</RoundButton>
+        <p role="status" aria-live="polite" style={{ margin: 0 }}>{status}</p>
+      </form>
+
+      <RoundButton tone="sky" onClick={onDone}>{t.back}</RoundButton>
+    </main>
+  );
+}
+
+export function SettingsScreen({ onDone }) {
+  return (
+    <ParentGate onCancel={onDone}>
+      <SettingsForm onDone={onDone} />
+    </ParentGate>
+  );
+}

diff --git a/src/pages/ProfileSettings.tsx b/src/pages/ProfileSettings.tsx
new file mode 100644
