+++ b/src/pages/ProfileSettings.tsx
@@ -0,0 +1,147 @@
+import { useState } from 'react';
+import { Field, Button } from '../ui';
+import { PERMISSIONS, requirePermission, type Permission } from '../auth/permissions';
+import { audit } from '../audit/log';
+
+export type NotificationPreferences = {
+  approvalRequests: boolean;
+  exportReady: boolean;
+  exportExpiring: boolean;
+  emailCopies: boolean;
+};
+
+export type ProfileSettingsValues = {
+  displayName: string;
+  notifications: NotificationPreferences;
+};
+
+type Staff = { id: string; permissions: Permission[] };
+
+type Props = {
+  staff: Staff;
+  initial: ProfileSettingsValues;
+  onSave: (values: ProfileSettingsValues) => Promise<void>;
+};
+
+const DISPLAY_NAME_MAX = 64;
+const AUDIT_REASON = 'Self-service settings change';
+
+const NOTIFICATION_OPTIONS: { key: keyof NotificationPreferences; label: string; hint: string }[] = [
+  { key: 'approvalRequests', label: 'Approval requests', hint: 'A change you submitted, or one assigned to you, needs approval.' },
+  { key: 'exportReady', label: 'Export ready', hint: 'An export you requested is ready to download.' },
+  { key: 'exportExpiring', label: 'Export expiring', hint: 'An export you requested expires in 24 hours. Exports expire 7 days after creation.' },
+  { key: 'emailCopies', label: 'Email copies of notifications', hint: 'Emails contain the event type and a link only. Customer data is not included.' },
+];
+
+function validateDisplayName(value: string): string | undefined {
+  const trimmed = value.trim();
+  if (trimmed.length === 0) return 'Enter a display name.';
+  if (trimmed.length > DISPLAY_NAME_MAX) return `Display name must be ${DISPLAY_NAME_MAX} characters or fewer.`;
+  return undefined;
+}
+
+export function ProfileSettings({ staff, initial, onSave }: Props) {
+  requirePermission(staff, PERMISSIONS.PROFILE_EDIT_SELF);
+
+  const [saved, setSaved] = useState(initial);
+  const [displayName, setDisplayName] = useState(initial.displayName);
+  const [notifications, setNotifications] = useState(initial.notifications);
+  const [nameError, setNameError] = useState<string>();
+  const [status, setStatus] = useState<{ kind: 'ok' | 'error'; text: string }>();
+  const [saving, setSaving] = useState(false);
+
+  const trimmedName = displayName.trim();
+  const nameChanged = trimmedName !== saved.displayName;
+  const notificationsChanged = (Object.keys(notifications) as (keyof NotificationPreferences)[]).some(
+    (k) => notifications[k] !== saved.notifications[k],
+  );
+  const dirty = nameChanged || notificationsChanged;
+
+  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
+    event.preventDefault();
+    requirePermission(staff, PERMISSIONS.PROFILE_EDIT_SELF);
+    setStatus(undefined);
+
+    const error = validateDisplayName(displayName);
+    setNameError(error);
+    if (error || !dirty) return;
+
+    const next: ProfileSettingsValues = { displayName: trimmedName, notifications };
+    setSaving(true);
+    try {
+      await onSave(next);
+      const target = `staff:${staff.id}`;
+      if (nameChanged) {
+        await audit.record({ actor: staff.id, action: 'profile.display_name.update', target, reason: AUDIT_REASON });
+      }
+      if (notificationsChanged) {
+        await audit.record({ actor: staff.id, action: 'profile.notifications.update', target, reason: AUDIT_REASON });
+      }
+      setSaved(next);
+      setDisplayName(next.displayName);
+      setStatus({ kind: 'ok', text: 'Changes saved.' });
+    } catch {
+      setStatus({ kind: 'error', text: 'Changes were not saved. Try again or contact the service desk.' });
+    } finally {
+      setSaving(false);
+    }
+  }
+
+  function handleDiscard() {
+    setDisplayName(saved.displayName);
+    setNotifications(saved.notifications);
+    setNameError(undefined);
+    setStatus(undefined);
+  }
+
+  return (
+    <main className="ld-page">
+      <h1>Profile settings</h1>
+      <form onSubmit={handleSubmit} noValidate>
+        <section aria-labelledby="profile-heading">
+          <h2 id="profile-heading">Profile</h2>
+          <Field
+            id="displayName"
+            label="Display name"
+            hint="Shown to other staff and in the audit trail. Your staff ID does not change."
+            error={nameError}
+          >
+            <input
+              name="displayName"
+              value={displayName}
+              maxLength={DISPLAY_NAME_MAX}
+              autoComplete="name"
+              onChange={(e) => setDisplayName(e.target.value)}
+              onBlur={() => setNameError(validateDisplayName(displayName))}
+            />
+          </Field>
+        </section>
+
+        <fieldset>
+          <legend>Notifications</legend>
+          {NOTIFICATION_OPTIONS.map((opt) => (
+            <Field key={opt.key} id={`notify-${opt.key}`} label={opt.label} hint={opt.hint}>
+              <input
+                type="checkbox"
+                name={opt.key}
+                checked={notifications[opt.key]}
+                onChange={(e) => setNotifications({ ...notifications, [opt.key]: e.target.checked })}
+              />
+            </Field>
+          ))}
+        </fieldset>
+
+        <div className="ld-toolbar">
+          <Button type="submit" variant="primary" disabled={saving || !dirty}>
+            {saving ? 'Saving changes' : 'Save changes'}
+          </Button>
+          <Button onClick={handleDiscard} disabled={saving || !dirty}>Discard changes</Button>
+        </div>
+
+        <p role="status" aria-live="polite" className={status ? `ld-status ld-status--${status.kind}` : undefined}>
+          {status?.text}
+        </p>
+      </form>
+    </main>
+  );
+}

