@@ -1,10 +1,32 @@
 const KEY = 'sprout.progress.v2';

+const DEFAULTS = { name: 'Reader', seeds: 0, sprouts: [], storiesRead: [], dailyGoalMinutes: 10, reminders: true };
+
+export const NAME_MAX_LENGTH = 20;
+
 export function loadProgress() {
   const raw = globalThis.localStorage?.getItem(KEY);
-  return raw ? JSON.parse(raw) : { name: 'Reader', seeds: 0, sprouts: [], storiesRead: [], dailyGoalMinutes: 10, reminders: true };
+  return raw ? { ...DEFAULTS, ...JSON.parse(raw) } : { ...DEFAULTS };
 }

 export function saveProgress(progress) {
   globalThis.localStorage?.setItem(KEY, JSON.stringify(progress));
 }
+
+/**
+ * Checks a reader's display name. It must be a first name or nickname only
+ * (see PARENTS.md), so we reject anything that looks like an email or a full name.
+ * Returns an error key from copy.settings.nameErrors, or null when the name is fine.
+ */
+export function checkDisplayName(value) {
+  const name = value.trim();
+  if (!name) return 'empty';
+  if (name.length > NAME_MAX_LENGTH) return 'tooLong';
+  if (name.includes('@') || /\s/.test(name)) return 'oneName';
+  return null;
+}
+
+export function saveSettings({ name, reminders }) {
+  const progress = loadProgress();
+  saveProgress({ ...progress, name: name.trim(), reminders: Boolean(reminders) });
+}
diff --git a/src/screens/SettingsScreen.jsx b/src/screens/SettingsScreen.jsx
new file mode 100644
index 0000000..9bf73c2
--- /dev/null
+++ b/src/screens/SettingsScreen.jsx
@@ -0,0 +1,119 @@
+import { useState } from 'react';
+import copy from '../copy/en.json';
+import { ParentGate } from '../components/ParentGate';
+import { RoundButton } from '../components/RoundButton';
+import { loadProgress, saveSettings, checkDisplayName, NAME_MAX_LENGTH } from '../data/progress';
+
+const text = copy.settings;
+
+const fieldStyle = {
+  minHeight: 'var(--sprout-tap)',
+  borderRadius: 'var(--sprout-radius-pill)',
+  fontSize: 'var(--sprout-text-body)',
+  fontFamily: 'inherit',
+  padding: '0 24px',
+  border: '3px solid var(--sprout-leaf-deep)',
+  color: 'var(--sprout-ink)',
+  background: '#fff',
+};
+
+function SettingsForm({ onDone }) {
+  const [initial] = useState(loadProgress);
+  const [name, setName] = useState(initial.name);
+  const [reminders, setReminders] = useState(initial.reminders);
+  const [error, setError] = useState(null);
+  const [saved, setSaved] = useState(false);
+
+  function handleSubmit(e) {
+    e.preventDefault();
+    const problem = checkDisplayName(name);
+    setError(problem);
+    if (problem) return;
+    saveSettings({ name, reminders });
+    setSaved(true);
+  }
+
+  return (
+    <main
+      className="settings"
+      style={{
+        background: 'var(--sprout-cream)',
+        color: 'var(--sprout-ink)',
+        fontFamily: 'var(--sprout-font)',
+        fontSize: 'var(--sprout-text-body)',
+        lineHeight: 'var(--sprout-line)',
+        padding: 'var(--sprout-gap)',
+      }}
+    >
+      <h1 style={{ fontSize: 'var(--sprout-text-title)' }}>{text.title}</h1>
+
+      <form onSubmit={handleSubmit} style={{ display: 'grid', gap: 'calc(var(--sprout-gap) * 1.5)' }}>
+        <section style={{ display: 'grid', gap: 'var(--sprout-gap)' }}>
+          <label htmlFor="settings-name">{text.nameLabel}</label>
+          <p id="settings-name-help" style={{ margin: 0 }}>{text.nameHelp}</p>
+          <input
+            id="settings-name"
+            type="text"
+            autoComplete="off"
+            maxLength={NAME_MAX_LENGTH}
+            value={name}
+            aria-describedby={error ? 'settings-name-help settings-name-error' : 'settings-name-help'}
+            aria-invalid={Boolean(error)}
+            onChange={(e) => { setName(e.target.value); setSaved(false); }}
+            style={fieldStyle}
+          />
+          {error && (
+            <p id="settings-name-error" role="alert" style={{ margin: 0, color: 'var(--sprout-soil)' }}>
+              {text.nameErrors[error].replace('{max}', NAME_MAX_LENGTH)}
+            </p>
+          )}
+        </section>
+
+        <section style={{ display: 'grid', gap: 'var(--sprout-gap)' }}>
+          <h2 style={{ fontSize: 'var(--sprout-text-body)', margin: 0 }}>{text.notificationsTitle}</h2>
+          <label
+            htmlFor="settings-reminders"
+            style={{
+              display: 'flex',
+              alignItems: 'center',
+              gap: 'var(--sprout-gap)',
+              minHeight: 'var(--sprout-tap)',
+              padding: '0 24px',
+              borderRadius: 'var(--sprout-radius-blob)',
+              background: '#fff',
+              cursor: 'pointer',
+            }}
+          >
+            <input
+              id="settings-reminders"
+              type="checkbox"
+              role="switch"
+              checked={reminders}
+              aria-describedby="settings-reminders-help"
+              onChange={(e) => { setReminders(e.target.checked); setSaved(false); }}
+              style={{ width: 32, height: 32, accentColor: 'var(--sprout-leaf-deep)' }}
+            />
+            {text.remindersLabel}
+          </label>
+          <p id="settings-reminders-help" style={{ margin: 0 }}>{text.remindersHelp}</p>
+        </section>
+
+        <RoundButton type="submit">{text.save}</RoundButton>
+        {saved && <p role="status" style={{ margin: 0 }}>{text.saved}</p>}
+      </form>
+
+      <div style={{ marginTop: 'var(--sprout-gap)' }}>
+        <RoundButton tone="sky" onClick={onDone}>{text.back}</RoundButton>
+      </div>
+    </main>
+  );
+}
+
+/** Grown-up settings. Always opens behind the parental gate (PARENTS.md). */
+export function SettingsScreen({ onDone }) {
+  return (
+    <ParentGate onCancel={onDone}>
+      <SettingsForm onDone={onDone} />
+    </ParentGate>
+  );
+}

