new file mode 100644
index 0000000..f8b9fa5
--- /dev/null
+++ b/src/pages/ProfileSettings.tsx
@@ -0,0 +1,146 @@
+import { useState } from 'react';
+import { Field, Button } from '../ui';
+import { PERMISSIONS, requirePermission, type Permission } from '../auth/permissions';
+import { audit } from '../audit/log';
+
+export type NotificationKey = 'caseAssigned' | 'approvalRequested' | 'exportReady';
+
+export type ProfileSettingsValues = {
+  displayName: string;
+  notifications: Record<NotificationKey, boolean>;
+};
+
+type Staff = { id: string; permissions: Permission[] };
+
+type Props = {
+  staff: Staff;
+  initial: ProfileSettingsValues;
+  onSave: (values: ProfileSettingsValues) => Promise<void>;
+};
+
+const NOTIFICATION_OPTIONS: { key: NotificationKey; label: string; hint: string }[] = [
+  { key: 'caseAssigned', label: 'Case assigned to me', hint: 'Sent when a case is assigned to your staff ID.' },
+  { key: 'approvalRequested', label: 'Approval requested', hint: 'Sent when an action is waiting for your approval.' },
+  { key: 'exportReady', label: 'Export ready', hint: 'Sent when an export you requested is ready to download.' },
+];
+
+const DISPLAY_NAME_MAX = 80;
+
+function formatTimestamp(date: Date) {
+  // 2026-11-11 14:05 UTC
+  return `${date.toISOString().slice(0, 16).replace('T', ' ')} UTC`;
+}
+
+function validateDisplayName(value: string): string | undefined {
+  const trimmed = value.trim();
+  if (trimmed.length === 0) return 'Enter a display name.';
+  if (trimmed.length > DISPLAY_NAME_MAX) return `Display name must be ${DISPLAY_NAME_MAX} characters or fewer.`;
+  return undefined;
+}
+
+export function ProfileSettings({ staff, initial, onSave }: Props) {
+  requirePermission(staff, PERMISSIONS.PROFILE_EDIT_SELF);
+
+  const [saved, setSaved] = useState<ProfileSettingsValues>(initial);
+  const [displayName, setDisplayName] = useState(initial.displayName);
+  const [notifications, setNotifications] = useState(initial.notifications);
+  const [nameError, setNameError] = useState<string>();
+  const [status, setStatus] = useState<{ kind: 'ok' | 'error'; message: string }>();
+  const [saving, setSaving] = useState(false);
+
+  const changedFields = [
+    displayName.trim() !== saved.displayName && 'displayName',
+    ...NOTIFICATION_OPTIONS.filter((o) => notifications[o.key] !== saved.notifications[o.key]).map(
+      (o) => `notifications.${o.key}`,
+    ),
+  ].filter((f): f is string => Boolean(f));
+
+  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
+    event.preventDefault();
+    const error = validateDisplayName(displayName);
+    setNameError(error);
+    if (error || changedFields.length === 0) return;
+
+    const next: ProfileSettingsValues = { displayName: displayName.trim(), notifications };
+    setSaving(true);
+    setStatus(undefined);
+    try {
+      requirePermission(staff, PERMISSIONS.PROFILE_EDIT_SELF);
+      await onSave(next);
+      await audit.record({
+        actor: staff.id,
+        action: 'profile.update',
+        target: `staff:${staff.id}`,
+        reason: `Self-service settings change: ${changedFields.join(', ')}`,
+      });
+      setSaved(next);
+      setDisplayName(next.displayName);
+      setStatus({ kind: 'ok', message: `Changes saved ${formatTimestamp(new Date())}.` });
+    } catch {
+      setStatus({ kind: 'error', message: 'Changes not saved. Try again or contact the service desk.' });
+    } finally {
+      setSaving(false);
+    }
+  }
+
+  function handleReset() {
+    setDisplayName(saved.displayName);
+    setNotifications(saved.notifications);
+    setNameError(undefined);
+    setStatus(undefined);
+  }
+
+  return (
+    <main className="ld-page">
+      <h1>Profile settings</h1>
+      <form onSubmit={handleSubmit} noValidate>
+        <section aria-labelledby="profile-heading">
+          <h2 id="profile-heading">Profile</h2>
+          <Field
+            id="displayName"
+            label="Display name"
+            hint={`Shown to other staff in LedgerDesk Admin. Your staff ID (${staff.id}) does not change. Maximum ${DISPLAY_NAME_MAX} characters.`}
+            error={nameError}
+          >
+            <input
+              name="displayName"
+              value={displayName}
+              maxLength={DISPLAY_NAME_MAX}
+              autoComplete="name"
+              required
+              onChange={(e) => setDisplayName(e.target.value)}
+              onBlur={() => setNameError(validateDisplayName(displayName))}
+            />
+          </Field>
+        </section>
+
+        <fieldset>
+          <legend>Email notifications</legend>
+          {NOTIFICATION_OPTIONS.map((option) => (
+            <Field key={option.key} id={`notify-${option.key}`} label={option.label} hint={option.hint}>
+              <input
+                type="checkbox"
+                name={`notify-${option.key}`}
+                checked={notifications[option.key]}
+                onChange={(e) => setNotifications({ ...notifications, [option.key]: e.target.checked })}
+              />
+            </Field>
+          ))}
+        </fieldset>
+
+        <div className="ld-toolbar">
+          <Button type="submit" variant="primary" disabled={saving || changedFields.length === 0}>
+            {saving ? 'Saving changes' : 'Save changes'}
+          </Button>
+          <Button onClick={handleReset} disabled={saving || changedFields.length === 0}>
+            Discard changes
+          </Button>
+        </div>
+
+        <p role="status" aria-live="polite" className={status ? `ld-status ld-status--${status.kind}` : undefined}>
+          {status?.message}
+        </p>
+      </form>
+    </main>
+  );
+}
